create table if not exists "Data_Retention_Policies"("Policy_ID" bigserial primary key,"Data_Type" text unique not null,"Retention_Days" int not null check("Retention_Days">0),"Archive_Before_Delete" boolean not null default true,"Enabled" boolean not null default false,"Updated_At" timestamptz not null default now());
insert into "Data_Retention_Policies"("Data_Type","Retention_Days","Enabled") values ('SECURITY_EVENTS',365,false),('AUDIT_LOGS',730,false),('NOTIFICATIONS',180,false),('ATTENDANCE_CHALLENGES',30,false) on conflict("Data_Type") do nothing;
create table if not exists "Privacy_Requests"("Request_ID" uuid primary key default gen_random_uuid(),"ID_User" text not null,"Request_Type" text not null check("Request_Type" in('EXPORT','DELETE_BIOMETRIC','RECTIFY','RESTRICT')),"Status" text not null default 'SUBMITTED' check("Status" in('SUBMITTED','IN_REVIEW','APPROVED','REJECTED','COMPLETED')),"Reason" text,"Handled_By" text,"Created_At" timestamptz not null default now(),"Completed_At" timestamptz);
create table if not exists "Performance_Snapshots"("Snapshot_ID" bigserial primary key,"Service_Name" text not null,"Metric_Name" text not null,"P50" numeric,"P95" numeric,"P99" numeric,"Sample_Count" int not null default 0,"Recorded_At" timestamptz not null default now());
create index if not exists idx_attendance_security_events_created on "Attendance_Security_Events"("Created_At" desc);
create index if not exists idx_notifications_target_read on "Notifications"("Target_User_ID","Read_At","Created_At" desc);
create index if not exists idx_shift_assignments_user_dates on "Work_Shift_Assignments"("ID_User","Valid_From","Valid_Until");
create or replace function platform_readiness_summary() returns jsonb language sql security definer as $$select jsonb_build_object('retentionPolicies',(select count(*) from "Data_Retention_Policies"),'privacyRequestsOpen',(select count(*) from "Privacy_Requests" where "Status" not in('COMPLETED','REJECTED')),'performanceSamples',(select coalesce(sum("Sample_Count"),0) from "Performance_Snapshots"),'generatedAt',now())$$;
create or replace function purge_expired_operational_data(p_dry_run boolean default true) returns jsonb language plpgsql security definer as $$declare n bigint:=0; begin select count(*) into n from "Notifications" where "Expires_At" is not null and "Expires_At"<now(); if not p_dry_run then delete from "Notifications" where "Expires_At" is not null and "Expires_At"<now(); end if; return jsonb_build_object('dryRun',p_dry_run,'expiredNotifications',n); end$$;